/* Manual de uso (pestaña Manual): secciones expandibles. */
(function () {
  const K = window.K;
  const S = [
    ['Primeros pasos', `<p>Al abrir la app ves el <b>Inicio</b> (o, si ya usaste una categoría en este dispositivo, directamente su pestaña <b>Hoy</b>): elige la categoría con la que vas a trabajar (Sub 15, 16, 18 o 20). Cada categoría tiene sus propios jugadores y registros, y el informe se presenta <b>combinado por pareja</b> (Sub 15-16 y Sub 18-20).</p>
      <p>Arriba a la derecha hay un selector para cambiar de categoría o volver al <b>Inicio</b> en cualquier momento. Abajo (o a la izquierda en pantallas grandes) están las secciones: Hoy, Informe, Registrar, Jugadores, Kine, Partidos, Manual y Ajustes (donde también está la versión de la app).</p>
      <p>Orden recomendado: 1) cargar la lista de jugadores, 2) revisar el calendario de Partidos, 3) registrar día a día, 4) al final del período abrir <b>Informe</b> y descargar el PDF.</p>`],
    ['Jugadores', `<ul><li><b>Agregar jugador:</b> botón “Agregar”. Completa <b>nombres, primer apellido y segundo apellido</b> (los tres son obligatorios en un jugador nuevo), la <b>categoría a la que pertenece</b> (Sub 15, 16, 18 o 20: es su categoría base, una sola; ahí está en las listas, los informes y su ficha), el año de nacimiento y la posición (Portero, Defensa, Volante o Delantero), todo eligiendo de listas. Si el jugador ya existe —también si está en el Archivo— la app no lo repite y te ofrece abrir su ficha. En el recuadro aparte <b>También juega en (solo para partidos)</b> marcas otras categorías donde puede ser convocado sin cambiar su ficha (en su ficha aparece “Pertenece a: Sub 16 · También juega en: Sub 20” y “Ha jugado en…”). Con la casilla <b>Jugador de plantel</b> el jugador lleva una etiqueta verde en la lista y en su ficha. También puedes subir una <b>foto</b>.</li>
      <li><b>Orden en el informe:</b> las fichas salen en el mismo orden en que ves la lista. <b>Arrastra</b> el asa ⠿ de cada jugador (con el dedo o el mouse) o usa las flechas ↑ ↓ para cambiarlo; “Volver al orden por nombre” lo restablece (por categoría y nombre).</li>
      <li><b>Pegar lista:</b> pega varios jugadores de una vez, <b>uno por línea</b>: <i>Nombres Apellido1 Apellido2; año de nacimiento</i> (también sirve copiar desde Excel). Eliges la categoría en una lista y se aplica a todos. Antes de guardar ves cada línea marcada como <b>Nuevo</b>, <b>Duplicado</b> o <b>Faltan apellidos</b>; los duplicados no se agregan y las líneas sin apellidos hay que corregirlas.</li>
      <li><b>Inscritos y Archivo:</b> arriba de la lista hay dos pestañas. <b>Inscritos</b> son los jugadores del día a día; <b>Archivo</b> guarda a los que se dieron de baja (ver “Cambio de año, categorías y archivo”).</li>
      <li><b>Filtros:</b> por categoría y posición; el buscador filtra por nombre.</li>
      <li><b>Lesionados en la lista:</b> cada jugador con una lesión sin alta muestra la insignia roja <b>Lesionado</b> y la fecha de su <b>última atención</b>. El botón <b>Solo lesionados</b> deja en la lista solo a quienes están lesionados.</li>
      <li><b>Buscador global:</b> la lupa de la barra superior abre una hoja para buscar a cualquier jugador (inscrito o archivado, de las dos parejas de categorías) por cualquier parte de su nombre o apellidos, sin importar tildes ni mayúsculas. Se puede activar “Solo lesionados”. Al tocar un resultado se abre su ficha, cambiando de categoría o informe si hace falta. Funciona sin conexión.</li>
      <li><b>Ficha del jugador:</b> toca un jugador para ver sus datos, sus lesiones y molestias, atenciones, controles, exámenes y su <b>estado actual</b> si está lesionado.</li>
      <li><b>Campos adicionales:</b> en Ajustes puedes crear datos extra para la ficha (texto, lista, número o sí/no).</li>
      <li>Si estás registrando y falta un jugador, en cualquier lista de jugadores elige <b>“＋ Agregar jugador nuevo…”</b> sin salir del formulario.</li></ul>`],
    ['Registrar atenciones y casos', `<p>La sección <b>Registrar</b> tiene cinco botones (la atención en verde):</p>
      <ul><li><b>Registrar atención:</b> es un solo formulario que reemplaza a los antiguos “atención”, “lesión / molestia” y “medicamento”. Paso a paso: 1) <b>origen</b> (si lo que se atiende ocurrió con nosotros —entrenamiento, partido— o fuera de Santiago Wanderers, por ejemplo en la casa o jugando con amigos); 2) <b>período de la temporada</b> (pretemporada, campeonato 1.er o 2.º semestre, intertemporada, playoff); 3) <b>tipo</b> (molestia, enfermedad, primeros auxilios u otras); 4) <b>intervención realizada</b> con su cantidad (todas las de siempre más manejo de carga, farmacología, derivación externa, manejo de sangrado, ortopedia e inmovilización); 5) <b>comentarios de la intervención</b>. Puedes registrar a varios jugadores a la vez. Si marcas farmacología aparece el medicamento y la dosis, y se registra solo.</li>
      <li><b>Registrar lesión:</b> tipo (lesión o molestia), título, <b>gravedad según días fuera</b> (mínima 1-3 días · leve 4-7 · moderada 8-28 · grave más de 28 · o <b>por definir</b>), zona en el mapa corporal (muslo derecho anterior/posterior, pierna anterior/posterior, dedos, ortejos, cadera e ingle por separado…), <b>ocurrió en</b>, terreno, inicio y alta. Una lesión sin alta aparece sola en la pestaña <b>Kine</b>. Si ocurrió en <b>entrenamiento</b> se pregunta la parte (calentamiento, parte física en gimnasio o cancha, parte técnica); si fue en <b>partido</b> se pregunta el momento (pre, durante, entretiempo, post) y si tuvo que abandonar el terreno. <b>Limita entrenamiento</b> (solo en molestias de entrenamiento u otros): elige Sí o No; con Sí indicas los días (o <b>aún no definido</b>) y qué parte limita. Cuando una molestia resulta ser una lesión (por ejemplo dolor de hombro que en el seguro se diagnostica como esguince acromioclavicular) usa <b>Convertir en lesión</b> al editar la molestia: <b>la molestia se conserva</b> con todo lo que hiciste ese día y se crea la lesión con el diagnóstico; en el informe la molestia dice “terminó siendo la lesión: …” y la lesión “comenzó como molestia: …”.</li>
      <li><b>Convertir una molestia en lesión:</b> dentro de la molestia toca “Convertir en lesión”. La molestia <b>se mantiene en el registro</b> con la nota de que terminó siendo esa lesión, pero se le <b>borran</b> la gravedad, el alta, las semanas de baja y si limita el entrenamiento (días y parte): esos datos quedan solo en la lesión.</li>
      <li><b>Control médico, Examen y Cirugía:</b> fecha, jugador, nombre y notas.</li></ul>
      <p>Debajo están los <b>últimos registros</b> con <b>filtros</b>: por tipo (atención, lesión, molestia, control, examen, medicamento, cirugía), por jugador y un buscador de texto (por ejemplo “RNM” para ver todos los exámenes de resonancia). Toca un registro para editarlo o eliminarlo.</p>
      <p><b>Ajuste manual:</b> ya no es un botón de Registrar. Si necesitas corregir un total, toca el número en Informe → Totales del período.</p>
      <p><b>Alta de una lesión:</b> al poner la fecha de alta (aquí o en la pestaña Kine) se calculan los días de baja, la disponibilidad y el retorno promedio.</p>`],
    ['Uso diario más rápido', `<p>Pensado para usarlo en la cancha, con una mano y con poco tiempo.</p>
      <ul><li><b>Hoy:</b> al elegir una categoría se abre la pestaña <b>Hoy</b> (la primera de la barra). Arriba está el botón grande <b>Registrar atención</b> y debajo <b>Repetir última</b>, <b>Varios jugadores</b> y <b>Lesión</b>. Si hay una categoría distinta a la tuya, la cambias con los botones Sub 15, 16, 18 y 20.</li>
      <li><b>La app recuerda tu categoría:</b> al abrirla en este celular o computador vuelve directo a “Hoy” de la última categoría que usaste (la de tu compañero queda en su propio dispositivo). Para ir al Inicio usa el selector de arriba.</li>
      <li><b>Lesionados activos:</b> cada uno muestra la zona, el <b>día de baja</b> y el próximo control. Con un toque marcas su asistencia de hoy: <b>✓ asistió</b>, <b>✗ no asistió</b> o <b>en casa</b> (es la misma asistencia de la pestaña Kine; tocar de nuevo el mismo botón la quita y aparece “Deshacer”). <b>Atender</b> abre la atención ya con el jugador y su lesión elegidos.</li>
      <li><b>Controles de hoy y vencidos:</b> los controles, exámenes y procedimientos que tocan hoy, y los que ya pasaron y siguen con la fecha vieja en la ficha del lesionado (si el control ya se registró, no se marca como vencido). <b>Sin atención hace más de 5 días:</b> lesionados a quienes no les registras atenciones hace más de cinco días. <b>Partidos de hoy y mañana</b> de la categoría.</li>
      <li><b>Elegir jugador:</b> el campo abre una lista con <b>buscador</b> (no importan las tildes ni las mayúsculas), los <b>5 recientes</b> (los últimos que usaste en este dispositivo) y el filtro <b>Lesionados</b>. Los lesionados llevan una insignia roja. Se usa igual en atención, lesión, control, examen, partidos, Kine y seguro. Si el jugador no existe, “Agregar jugador nuevo”.</li>
      <li><b>Varios jugadores a la vez:</b> en la atención toca “Aplicar a varios jugadores”: hay buscador, atajos <b>Lesionados</b>, <b>Último grupo</b>, <b>Todos</b> y <b>Ninguno</b>, y un contador fijo de seleccionados. Los mismos tratamientos se guardan para todos.</li>
      <li><b>Guardar y registrar otro:</b> guarda la atención y deja el formulario abierto con las intervenciones ya marcadas para que solo elijas al siguiente jugador.</li>
      <li><b>Más usadas y plantillas:</b> arriba de las intervenciones aparecen las <b>5 más usadas</b> de este informe. <b>Plantillas:</b> marca intervenciones, toca “Guardar como plantilla”, ponle nombre (ej. “Post partido”) y desde entonces un toque en su botón rellena todo. La “×” elimina una plantilla.</li>
      <li><b>Repetir última atención:</b> en la ficha del jugador, en Registrar o dentro de la atención, copia las intervenciones y la lesión de su última atención (la fecha es hoy).</li>
      <li><b>Lesión asociada:</b> si el jugador tiene una lesión o molestia abierta, se elige sola en la atención (puedes cambiarla). No se guarda una atención sin ninguna intervención ni comentario.</li>
      <li><b>“Más detalles”:</b> la atención y la lesión muestran solo lo esencial; el origen, el período, el tipo, el medicamento, los comentarios y los datos clínicos están en el bloque plegable “Más detalles”.</li>
      <li><b>Deshacer:</b> al eliminar una atención, lesión, control o examen, un partido o una asistencia, aparece por 6 segundos el aviso con <b>Deshacer</b>; lo devuelve tal cual estaba, en el mismo lugar. El botón Eliminar quedó separado de Guardar para no tocarlo por error.</li>
      <li><b>Citados y evaluación rápida (Partidos):</b> en cada partido, el paso previo <b>Citados</b> te deja marcar quiénes están citados (buscador, <b>Marcar todos</b>, <b>Ninguno</b>, <b>Quitar lesionados</b> y <b>Copiar citados del partido anterior</b>). Con citados, los minutos se anotan solo para ellos y <b>Completar con 90 a los citados sin minutos</b> nunca toca a quien no fue citado. El botón grande <b>Evaluación en cancha rápida</b> registra en 4 toques (abrir, jugador, minuto, <b>Siguió jugando</b> o <b>Se retiró</b>) y se puede deshacer.</li>
      <li><b>Kine más rápida:</b> la lista de lesionados va primero, con filas compactas (zona, día de baja, próximo control y asistencia en un toque). <b>Todos asistieron</b> marca a quienes aún no tienen marca ese día (con confirmación y Deshacer). Un aviso rojo muestra los <b>controles vencidos</b>. El calendario de fechas importantes quedó plegado.</li>
      <li><b>Botones más grandes:</b> todo lo que se toca mide al menos 44 px. Las flechas y asas para cambiar el orden aparecen solo al tocar <b>Ordenar</b> (Jugadores y Partidos).</li></ul>`],
    ['Registro clínico completo', `<p>Es el registro con <b>todo lo anotado en la app</b>, incluso lo que no sale en el PDF: notas, comentarios, fechas de inicio y alta, días que tomó cada caso, mecanismo, limitaciones de entrenamiento, atenciones, ajustes manuales y minutos jugados.</p>
      <ul><li><b>Dónde está:</b> botón “Registro clínico completo” en la pestaña Informe y en Registrar.</li>
      <li><b>Categorías:</b> solo Sub 15, solo Sub 16, solo Sub 18, solo Sub 20, toda la pareja Sub 15-16, toda la pareja Sub 18-20 o todas las categorías.</li>
      <li><b>Resumen visual:</b> arriba de la lista hay gráficos con indicadores, registros por mes, tipos de registro, gravedad, línea de tiempo de lesiones y molestias, dónde ocurrió, zonas, tratamientos, medicamentos y jugadores con más registros. Se ajustan al alcance, período y jugador elegidos y salen también en el PDF.</li>
      <li><b>Filtros:</b> jugador, tipo de registro, período, agrupar por fecha o por jugador, y buscador de texto.</li>
      <li><b>Exportar:</b> “PDF” (ventana de impresión) o “Excel (CSV)” para abrir en una planilla.</li></ul>`],
    ['Kine (lesionados, informe semanal, seguro)', `<p>La pestaña <b>Kine</b> junta a <b>todos los lesionados de todas las categorías</b> (de la Sub 20 a la Sub 15). Tiene cuatro secciones:</p>
      <ul><li><b>Seguimiento:</b> arriba, un <b>calendario con las fechas importantes</b> (próximo control en morado, próximo examen en naranja, próximo procedimiento en turquesa, cirugía en negro y una <b>L roja</b> el día de cada lesión). Con el <b>interruptor</b> eliges ver <b>todo el histórico</b> (incluye controles, exámenes y cirugías ya realizados) o <b>solo las próximas fechas</b> y la lista de las próximas fechas. Los controles, exámenes y cirugías que registres con <b>fecha futura</b> aparecen ahí como próximas fechas (aunque el jugador no tenga lesión) y no se cuentan en los totales hasta que llegue el día. Abajo, los lesionados <b>del día elegido</b> (uno lesionado el 10-10 no aparece el 09-10; sale de la lista cuando se le da el alta), cada uno con foto, nombre, categoría, posición y año; a la derecha la <b>lesión (diagnóstico)</b>, la <b>fecha de lesión</b>, los <b>días de baja hasta ahora</b> y su <b>estado</b> (en rehabilitación, en reintegro deportivo o en espera). Cuando registras una lesión en Registrar, el jugador aparece aquí solo; con <b>+ Agregar</b> también puedes partir desde esta pestaña.</li>
      <li><b>Asistencia diaria:</b> con el selector de día (hoy por defecto) marca <b>✓</b> si vino o <b>✗</b> si no. El día de la lesión aparece una <b>L</b> en un cuadro rojo en vez de los botones. Con ✓ eliges <b>SK</b> o <b>RD</b> (reintegro deportivo) y, si es RD, <b>K</b>, <b>K+PF</b> o <b>K+PA</b> (kine + preparador de arqueros). La casita es <b>pauta en casa</b>. Con ✗ eliges el motivo: <b>no asiste</b>, <b>descanso</b>, <b>control médico</b>, <b>examen</b> o <b>procedimiento</b> (en el mismo horario del entrenamiento) o <b>enfermedad</b> (fiebre, virus…). Si no marcas nada se entiende que <b>no se entrena</b>. Tocar de nuevo el mismo botón lo deja en blanco. El % de asistencia <b>no cuenta</b> los días de descanso, pauta en casa, control, examen ni procedimiento; la <b>enfermedad sí cuenta</b> como no asistida y en la ficha y el informe queda el detalle (“3 días por enfermedad”).</li>
      <li><b>Ficha del lesionado:</b> toca su nombre. Ahí cambias el estado y escribes un comentario (aparece en su ficha del informe), el <b>próximo control</b>, <b>próximo examen</b> y <b>próximo procedimiento</b> (lista con ideas como ondas de choque, punción seca, electroestimulación…; también puedes escribir otro), las <b>semanas estimadas fuera</b>, la fecha de <b>alta</b> (con ella sale de la lista), si hubo <b>cirugía</b> y si es <b>recidiva</b>. Muestra la asistencia con <b>semáforo</b>: rojo bajo 80 %, amarillo 80–89 %, verde desde 90 %.</li>
      <li><b>Informe semanal:</b> aquí se hace todo el informe de la semana: un <b>comentario general</b>, la tabla de lesionados (Sub 20 a Sub 15) con diagnóstico, días de baja, % de asistencia a kinesiología, estado y un <b>comentario de la semana por jugador</b> que escribes en la misma fila, y los <b>próximos controles y exámenes</b>. Cambia de semana con las flechas y descárgalo en PDF. Con <b>Categorías del informe</b> eliges qué sacar: <b>todas juntas</b>, <b>de a dos</b> (Sub 15 y 16, o Sub 18 y 20) o <b>una sola</b>; también puedes marcar las casillas de cada categoría. La vista y el PDF incluyen solo las elegidas (el comentario general es el mismo).</li>
      <li><b>Calendario de fechas importantes:</b> además del día de la lesión (<b>L</b>) y de los controles, exámenes, procedimientos y cirugías, marca el <b>inicio del reintegro deportivo</b> (<b>R</b>) y el <b>alta</b> (<b>A</b>) de cada lesión. La fecha de inicio del reintegro es la del día en que pasó al estado “En reintegro deportivo” (la app propone hoy y puedes cambiarla en la ficha del lesionado). El alta es la fecha de alta kinésica (y la alta médica, si la anotaste).</li>
      <li><b>Seguro:</b> cada <b>activación del seguro</b> (un mismo jugador puede tener varias: por ejemplo una por una lesión de pie y otra, meses después, por una de hombro, cada una con su propio N.º de asistencia). Se registra el diagnóstico o motivo, RUT con formato automático 12.345.678-9, fecha de nacimiento, comuna, fecha de activación, clínica y su N.º de asistencia y sus <b>eventos</b>: control médico, examen (lista desplegable), procedimiento (lo escribes y queda guardado para sugerirlo la próxima vez), kinesiología, cirugía y hospitalización, cada uno con su <b>N.º de asistencia del seguro</b>. Abajo están las <b>estadísticas de uso del seguro</b>: “Activaciones iniciales de seguro (Sala de urgencias)” cuenta solo las activaciones, y “Activaciones + continuidad” suma además todos los eventos registrados (controles, exámenes, procedimientos, kinesiología, etc.). Cada activación es un cuadro pequeño con el nombre, la categoría y el <b>diagnóstico</b> (para saber a cuál corresponde): tócalo para abrir su detalle. Estos datos son privados: solo los ven los administradores.</li>
      <li><b>Asistencia anual:</b> calendario del año por jugador con colores: lesión, kinesiología (SK), reintegro deportivo, no asistió, pauta en casa, descanso, control, examen, otro procedimiento, kinesiología externa, cirugía y hospitalización. Los días con <b>L</b> (inicio de la lesión), <b>R</b> (inicio del reintegro deportivo) y <b>A</b> (alta) llevan su letra y la leyenda los explica.</li></ul>
      <p>Todo lo que anotas en Kine pasa solo al <b>informe descargable</b>: páginas de “Seguimiento kinésico”, “Lesionados en seguimiento” y “Uso del seguro” (sin datos personales), y el estado actual en la ficha de cada jugador.</p>`],
    ['Partidos', `<ul><li><b>Cómo se cargan:</b> cada rival es <b>un partido</b> y ahí eliges qué categorías juegan: normalmente <b>Sub 20 y Sub 18</b> el mismo día (con su resultado cada una), o <b>Sub 16 y Sub 15</b>. El botón <b>Agregar partido</b> pide rival, escudo, local o visita, fecha y las categorías. Si un partido se juega otro día, es otro partido.</li>
      <li><b>Calendario:</b> arriba ves el año completo o cada semestre con los días de partido marcados. Toca un partido para abrir su <b>informe</b>.</li>
      <li><b>Informe de partido:</b> arriba eliges <b>Sub 20 · Sub 18 · Combinado</b> (o Sub 16 · Sub 15 · Combinado). Con <b>Agregar atención</b> registras jugador, <b>cuándo</b> (pre partido, 1.er tiempo con minuto, entretiempo, 2.º tiempo con minuto, post partido; el minuto es <b>del tiempo</b>: el 83' del partido se anota como minuto 38 del 2.º tiempo y la app muestra “min 38' (83' del partido)”), tipo, si fue <b>atendido en cancha</b>, mecanismo, zona del cuerpo, la <b>intervención</b> (si solo entraste a evaluarlo y siguió jugando, usa <b>Evaluación en cancha</b>) y si <b>tuvo que retirarse</b>. Cada registro cuenta también como atención del jugador, así no se anota dos veces.</li>
      <li><b>Citados:</b> en cada categoría del partido elige primero a los <b>citados</b>. Con la lista definida, el selector de jugador de las atenciones muestra primero a los citados y a quienes jugaron (un toque en <b>Ver toda la categoría</b> abre al resto), los minutos se anotan para los citados y <b>+ Agregar jugador que no estaba citado</b> suma a quien jugó sin estarlo. La fila del partido muestra “N citados · M jugaron”. Un partido antiguo sin citados funciona como siempre (cuentan todos los de la categoría) y los informes dan los mismos números. <b>Evaluación en cancha rápida</b>: botón grande arriba del partido; eliges jugador, escribes el minuto del partido (opcional) y tocas <b>Siguió jugando</b> o <b>Se retiró</b>; queda como atención con la intervención “Evaluación en cancha”.</li>
      <li><b>Minutos jugados:</b> se anotan dentro del informe de partido (botón “Completar con 90 a los citados sin minutos”). Sirven para el informe de partidos y <b>no salen en la ficha</b> del jugador.</li>
      <li><b>Observaciones:</b> una por línea; en el PDF salen como viñetas. <b>Informe realizado por / partido cubierto por</b> aparece en el encabezado del PDF junto al escudo del rival.</li>
      <li><b>Lo que pasa en un partido va al informe de la categoría donde se juega.</b> Si un Sub 16 es citado a la Sub 20, sus minutos, atenciones y molestias de ese partido cuentan en el informe de la Sub 20 (no en el de la Sub 16); al final de ese informe aparece el apartado <b>Jugadores de otras categorías</b> con su resumen (si jugó y cuántos minutos). Solo si tuvo atenciones, molestias o lesiones se agrega su ficha; si todo estuvo bien, únicamente consta que jugó. Si juega en la Sub 16, todo va al informe de la Sub 16. Una atención de tipo molestia en un partido queda además registrada como <b>molestia</b> del jugador (con momento y si salió del campo) y aparece en el informe.</li>
      <li><b>Un jugador que juega en dos categorías</b> (por ejemplo Clemente Farías, Sub 16 subido a Sub 18): en sus datos (botón “Datos y foto”) deja <b>Categoría a la que pertenece: Sub 16</b> y marca <b>También juega en (solo para partidos): Sub 18</b>. Sigue en una sola lista y su ficha no se duplica, pero aparece disponible en los partidos de la otra categoría y su ficha muestra “Ha jugado en: Sub 16 (n), Sub 18 (n)”.</li>
      <li><b>Informe de todos los partidos:</b> al final de la pestaña eliges Todas (Sub 15 a 20), una categoría o una pareja y se descarga un PDF con resultados, atenciones, intervenciones, minutos y lesiones por jugador.</li>
      <li><b>Jugadores de plantel:</b> márcalo en sus datos (“Jugador de plantel”). Desde Partidos puedes descargar el <b>informe general de todos los jugadores de plantel</b>, el <b>informe de un partido</b> (por ejemplo contra Recoleta) y el informe de <b>los partidos que elijas</b>: en “Elegir partidos” marcas uno, varios o todos (se ve el rival, la fecha, la categoría y el resultado) y descargas el PDF. Ese informe se llama <b>Informe kinésico · Jugadores de plantel</b>: arriba un resumen solo de los jugadores de plantel (cuántos jugaron, minutos, atenciones, intervenciones, cuántos se retiraron y lesiones o molestias nuevas) y, por cada partido, una tabla con nombre, categoría, minutos jugados, si tuvo atención (Sí / No), intervención y comentarios (igual que en el informe de partido) y si se retiró (Sí / No). Todos los informes de partido dicen “Informe kinésico” en el título.</li>
      <li><b>Orden y fechas:</b> escribe la fecha de cada partido y arrastra <b>⠿</b> (o usa las flechas) para cambiar el orden en que salen en el informe.</li>
      <li>El <b>cuerpo técnico</b> de la portada también se edita aquí.</li></ul>`],
    ['Conmoción cerebral (SCAT5)', `<p>Sirve para <b>dejar registrado lo que hiciste</b> cuando un jugador recibe un golpe y hay sospecha de conmoción. <b>No es un diagnóstico y no es el SCAT5 oficial ni lo reemplaza</b>: es tu registro de apoyo para el informe del partido.</p>
      <ul><li><b>Dónde se abre:</b> en el informe del partido, botón rojo suave <b>Sospecha de conmoción</b>. También está dentro de <b>Agregar atención</b> y dentro de la <b>Evaluación en cancha rápida</b> (ahí se lleva el jugador y el minuto que ya elegiste).</li>
      <li><b>El formulario</b> tiene secciones que se abren y cierran: <b>¿Qué pasó?</b> (cuándo, minuto y mecanismo: golpe con codo u hombro, choque de cabezas, golpe de balón, caída o golpe contra el suelo, otro), <b>Signos observados</b>, <b>Banderas rojas</b>, <b>Evaluación realizada</b> (no realizada, en cancha, en camarín o SCAT5 completo, con los puntajes: síntomas 0–22, severidad 0–132, orientación 0–5, <b>memoria inmediata 0–30</b>, concentración 0–5, memoria diferida 0–10, equilibrio con errores 0–30 y coordinación) y <b>Resultado</b>. Si haces la evaluación con el asistente, esos puntajes se llenan solos.</li>
      <li><b>El SCAT5 en tres momentos:</b> en el formulario toca el botón grande <b>Evaluación SCAT5</b> (primero elige al jugador). Se abre una pantalla con <b>tres tarjetas</b> y puedes hacer solo la primera ahora y las otras después; cada tarjeta dice si está <b>Pendiente</b>, en <b>Borrador</b> o <b>Hecha a las hh:mm</b>, muestra su último resultado y trae el botón para iniciar, continuar o repetir. Toca <b>¿Cómo uso el SCAT5?</b> para ver la ayuda corta.</li>
      <li><b>1 · En cancha (2–3 min):</b> entras al campo a ver al jugador. Pasos con botones grandes: <b>banderas rojas</b> (si marcas una aparece el aviso de urgencia, la derivación queda en urgencia y puedes <b>terminar ahí</b>), <b>signos que ves</b>, <b>5 preguntas de memoria</b> (sí/no), <b>Glasgow y cuello</b> y la <b>decisión</b> (“Retirar del partido” viene marcado). Si todo es normal bastan unos 6 toques gracias a los botones “Respondió bien las 5” y “Glasgow 15 y cuello normal”. Queda anotada la hora. Aquí no se toman síntomas, cognitivo ni equilibrio.</li>
      <li><b>2 · En camarín (10–15 min):</b> al menos 10 minutos después, con el jugador tranquilo. Seis pasos que se pueden guardar y retomar: <b>antecedentes</b> (opcionales: conmociones previas y fecha aproximada de la última, migraña, TDAH, dificultades de aprendizaje, ansiedad o depresión y medicación), <b>síntomas</b> (22, de 0 a 6; calcula cuántos tiene y la severidad de 132; más si empeoran con el esfuerzo y el porcentaje que se siente normal), <b>cognitivo</b> (orientación de 5; memoria inmediata con 3 intentos de 10 palabras = 30, con lista A, B o C; concentración de 5 con dígitos al revés y meses al revés), <b>examen</b> (cuello, coordinación y equilibrio mBESS: <b>Iniciar 30 s</b>, el reloj avisa con vibración y sonido, errores de 0 a 10 por postura = 30), <b>memoria diferida</b> (va al final; un contador dice <b>Disponible en mm:ss</b> desde que terminó la memoria inmediata) y <b>decisión</b> (retiro, reemplazo, derivación, inicio del plan de retorno y notas).</li>
      <li><b>3 · Seguimiento (día siguiente y siguientes):</b> la fecha se puede cambiar. Pones los síntomas del día viendo al lado lo que respondió la vez anterior (botón <b>Copiar respuestas y ajustar</b>, con Deshacer); el cognitivo y el equilibrio son opcionales. Al final ves la <b>tabla de evolución por fecha</b> (síntomas, severidad, SAC cognitivo y mBESS) con flechas: la flecha muestra hacia dónde cambió el número y la palabra dice si <b>mejora</b>, está <b>igual</b> o <b>empeora</b>. Desde ahí abres el <b>retorno gradual</b> de seis etapas.</li>
      <li><b>Avisos en Hoy:</b> la tarjeta <b>SCAT5 pendiente</b> aparece cuando a un jugador con conmoción le falta la evaluación en camarín o lleva más de 24 horas sin seguimiento. Se quita al cumplir las seis etapas del retorno o al marcar <b>Alta de conmoción</b> en la pantalla de las tres tarjetas. El botón <b>Continuar</b> te lleva directo.</li>
      <li><b>Se guarda solo:</b> cada respuesta queda guardada. Puedes tocar <b>Guardar y salir</b> (o la X, o el gesto atrás) y volver más tarde. “Evaluación realizada” queda sola como <b>En cancha</b>, <b>En camarín</b> o <b>SCAT5 completo</b> (cancha y camarín terminados), y los puntajes del formulario son los de la evaluación más reciente de cada tipo. Una evaluación hecha con la versión 1.6.1 pasa sola a este formato.</li>
      <li><b>Ficha SCAT5 (PDF):</b> ficha Carta con el escudo del club: datos, cada evaluación con su fecha y hora, los puntajes y, si hay seguimientos, una página con la tabla de evolución. Está en la pantalla de las tres tarjetas, en el formulario de la conmoción, en el seguimiento de Kine, al abrir la lesión desde la ficha del jugador y en su línea de tiempo, donde <b>cada evaluación aparece como una entrada</b> (filtro “Evaluaciones SCAT5”). El informe del partido muestra una línea por evaluación y la tabla de evolución.</li>
      <li><b>El SCAT5 oficial:</b> en la pantalla de las tres tarjetas, en la ayuda, en el formulario, en Ajustes → Documentos y aquí puedes <b>descargar el formulario oficial en español (PDF)</b>, sin modificar, para imprimirlo o llevarlo.{{SCAT5_OFICIAL}} <i>SCAT5 © Concussion in Sport Group 2017 · para uso de profesionales de la salud.</i> La descarga funciona en la app instalada desde GitHub (no en la versión de una sola página).</li>
      <li><b>Importante:</b> <b>Registro de apoyo inspirado en la estructura de la evaluación SCAT5 (Concussion in Sport Group, 2017). No es el SCAT5 oficial ni lo reemplaza. Textos y listas propios. Para el formulario oficial, use el documento original.</b> Un resultado normal no descarta una conmoción; la decisión es clínica. <b>Nadie vuelve a jugar el mismo día de la lesión</b>, y la evaluación completa no se puede hacer bien en menos de 10 minutos: por eso en la cancha solo se hace la parte inmediata. Pensado para personas de 13 años o más (de la Sub 15 en adelante).</li>
      <li><b>Banderas rojas:</b> si marcas cualquiera, aparece un aviso rojo <b>“Derivación urgente a servicio de urgencia”</b> y la derivación queda marcada sola (la puedes cambiar).</li>
      <li><b>Resultado:</b> “Retirado del partido” viene marcado, porque con sospecha de conmoción el jugador no vuelve a jugar ese día. Además anotas si se hizo el reemplazo, la derivación, la fecha en que se inició el plan de retorno gradual, si <b>se informó a la organización del torneo</b> (dentro de 24 horas, por ejemplo CONMEBOL), el informe médico del reemplazo (opcional) y notas.</li>
      <li><b>Qué se crea solo:</b> al guardar queda la atención del jugador (con “Evaluación en cancha”) y una lesión llamada <b>“Conmoción cerebral (sospecha)”</b> en la cabeza, con gravedad “por definir”. El jugador aparece como <b>Lesionado</b> con la insignia <b>Conmoción</b> en Hoy, Kine y su ficha.</li>
      <li><b>Retorno gradual:</b> en la ventana de seguimiento de Kine y al editar la lesión hay seis etapas, cada una con casilla y fecha: reposo relativo; actividad aeróbica ligera; ejercicio específico del fútbol sin contacto; entrenamiento sin contacto con progresión; entrenamiento con contacto completo (tras el alta médica); vuelta al juego. Se ve el avance (por ejemplo 3 de 6) en la ficha del jugador.</li>
      <li><b>En los informes:</b> si hubo conmociones, el informe de partido (de una categoría o combinado), el informe de todos los partidos, el informe de jugadores de plantel y las páginas del informe del período traen la sección <b>Conmociones cerebrales (SCAT5)</b> con una tabla <b>breve</b> (jugador, minuto, banderas rojas, qué evaluaciones se hicieron con sus puntajes, retirado y derivación) y el contador <b>conmociones</b>. En la pantalla del partido, cada fila tiene el botón <b>Ver informe SCAT5 completo</b> y arriba de la tabla está <b>Informe SCAT5 (PDF)</b>, que saca solo las fichas SCAT5 completas de ese partido (sin el resto del informe). Si no hubo ninguna, los informes quedan exactamente como siempre.</li>
      <li><b>En la ficha:</b> aparece en el historial (la lesión y el partido), en el registro clínico completo y en el PDF y el CSV de la ficha. Al editar o eliminar la atención del partido se actualiza o se quita la lesión creada sola (se puede deshacer por unos segundos).</li></ul>`],
    ['El informe y el PDF', `<ul><li><b>Descargar PDF:</b> en Informe hay una tarjeta con un botón por cada informe: <b>único Sub 15, único Sub 16, combinado 15-16</b> (o único 18, único 20, combinado 18-20) y el <b>informe general Sub 15 a 20</b> para el cuerpo técnico. El archivo se genera en la app y se abre <b>Compartir / Guardar</b> (funciona en iPhone).</li>
      <li><b>Período:</b> anual, semestres, trimestres o personalizado. Todos los números se recalculan solos.</li>
      <li><b>Totales y textos:</b> toca un número para ver su detalle o sumarle un ajuste manual. Las <b>conclusiones</b> y <b>objetivos</b> salen en la última página (el informe general tiene su propio texto).</li>
      <li><b>Incluir los datos de partidos en el informe general:</b> casilla debajo de Conclusiones y objetivos. Muestra u oculta las páginas “Atenciones en partidos” y “Detalle por partido” del informe; los totales del resumen y los informes de cada partido no cambian. Se guarda por año: en 2026 viene <b>apagada</b> (no todas las atenciones de partidos estaban registradas) y desde 2027 viene <b>encendida</b>; el asistente “Iniciar temporada” la deja encendida.</li>
      <li><b>Vista previa:</b> portada, calendario por rival, resumen final, páginas del equipo, seguimiento kinésico, atenciones en partidos, ficha de cada jugador y conclusiones.</li></ul>
      <p>La ficha incluye: edad y pierna dominante, molestias y lesiones (con el <b>lado</b>), días de baja y % de disponibilidad (el cuadro se llama <b>Disponibilidad para entrenar y jugar</b> y explica que es el porcentaje de días del período en que el jugador estuvo sin lesión activa, es decir, disponible para el equipo), historial de lesiones (nombre y año) y de cirugías (nombre y fecha), asistencia a kinesiología con semáforo, número de controles y exámenes, mapa corporal, anillo de intervenciones y <b>Comentarios área kinésica</b>.</p>`],
    ['Indicadores y tratamientos', `<ul><li><b>Indicadores del resumen</b> (Ajustes): elige cuáles aparecen en las páginas de “Resumen final”, en qué orden (flechas) y si se ocultan (ojo). Con “Nuevo” creas indicadores propios.</li>
      <li><b>Tratamientos</b> (Ajustes): son los que aparecen al registrar una atención. Puedes crear nuevos, cambiar su nombre e ícono, y decidir si cuentan como intervención. Cada tratamiento genera su propio total.</li></ul>`],
    ['Cambio de año, categorías y archivo', `<p>Cada año los jugadores cambian de categoría, algunos salen y llegan otros. Esta sección explica cómo hacerlo <b>sin perder nada</b>.</p>
      <p><b>1. Empezar un año nuevo (una vez al año)</b></p>
      <ul><li>Cuando empieza el año, en el <b>Inicio</b> aparece un aviso amarillo con el botón <b>“Iniciar temporada 2027”</b> (también está en <b>Ajustes → Nueva temporada</b>).</li>
      <li><b>Paso 1:</b> se descarga un respaldo de todos tus datos, por seguridad, y sigues.</li>
      <li><b>Paso 2:</b> por cada jugador eliges con una lista: <b>Sube a Sub X</b>, <b>Se queda</b> o <b>Sale</b> (Liberado, Cedido, Promovido o Retirado, con un motivo si quieres). Ya viene todo preparado: los Sub 15 suben a 16, los 16 a 18, los 18 a 20 y los 20 se quedan. A los Sub 20 que cumplen 20 años ese año se les sugiere salir (aparecen en amarillo). En cada categoría hay atajos: “Todos suben”, “Todos se quedan”, “Todos salen”. Puedes buscar a un jugador por nombre.</li>
      <li><b>Paso 3:</b> ves el resumen (cuántos suben, se quedan y salen) y confirmas. Se aplica todo de una vez; si algo falla, no se cambia nada.</li>
      <li>Al terminar, la guía te ofrece <b>“Cargar jugadores nuevos”</b> (con la Sub 15 ya elegida).</li>
      <li>Si el año ya estaba iniciado, la guía lo dice y no hace nada: no se puede iniciar dos veces.</li></ul>
      <p><b>2. Qué significa cada estado</b></p>
      <ul><li><b>Inscrito:</b> juega o entrena en el club este año.</li><li><b>Liberado:</b> el club terminó su vínculo con él.</li><li><b>Cedido:</b> está a préstamo en otro club.</li><li><b>Promovido al primer equipo:</b> subió al primer equipo.</li><li><b>Retirado:</b> dejó de jugar.</li></ul>
      <p>Todos los estados distintos de Inscrito mandan al jugador al <b>Archivo</b>: no se borra, conserva su ficha y su historial completos.</p>
      <p><b>3. Dar de baja, cambiar de categoría y volver a inscribir</b></p>
      <ul><li><b>Dar de baja:</b> abre la ficha del jugador (Jugadores → toca su nombre), baja hasta <b>Estado en el club</b> y toca <b>Dar de baja</b>. Elige el estado, la fecha de salida con el calendario y, si quieres, el motivo.</li>
      <li><b>Cambiar de categoría:</b> en la misma tarjeta, <b>Cambiar de categoría</b>. Eso cambia la <b>categoría a la que pertenece</b> (la base): eliges la nueva y desde qué fecha. Si el jugador solo juega a veces en otra categoría, <b>no la cambies</b>: usa <b>También juega en</b>, dentro de sus datos (la ventana trae un atajo). Si pasa del informe Sub 15-16 al Sub 18-20 (o al revés), la app avisa que su ficha y todo su historial se mueven al otro informe; al terminar queda en la nueva categoría mostrando su ficha.</li>
      <li><b>Volver a inscribir:</b> Jugadores → pestaña <b>Archivo</b> → toca al jugador → <b>Volver a inscribir</b> y elige la categoría.</li>
      <li><b>Eliminar definitivamente:</b> solo existe para jugadores del Archivo y pide escribir ELIMINAR. Borra la ficha y todos sus registros; úsalo solo si lo creaste por error.</li></ul>
      <p><b>4. El Archivo</b></p>
      <ul><li>Jugadores → pestaña <b>Archivo</b>. Tiene buscador (no importan las tildes ni las mayúsculas) y filtros por <b>estado</b> y por <b>año de salida</b>. Cada jugador muestra la categoría que tenía, su estado y su fecha de salida.</li>
      <li>Al abrir su ficha aparece una franja gris “Archivado · Liberado el 31-12-2026”.</li></ul>
      <p><b>5. Ver el informe de años anteriores</b></p>
      <ul><li>En <b>Informe</b>, cambia el <b>año</b> junto al período. Verás el informe <b>tal cual quedó</b> ese año: con los jugadores que estaban inscritos (también los que después salieron), la categoría que tenían entonces, sus lesiones y atenciones de esa fecha, y las conclusiones, objetivos y comentarios que se escribieron ese año.</li>
      <li>Arriba aparece “Estás viendo el 2026” con un enlace para volver al año actual.</li></ul>`],
    ['Ficha clínica del jugador', `<p>En la ficha de cada jugador (pestaña Jugadores) ahora hay más datos clínicos. Todos son <b>opcionales</b>: puedes llenar solo lo que te sirva.</p>
      <ul><li><b>Lesión o molestia → “Más detalles clínicos”</b> (un bloque que se abre con un toque; también está en la ventana de seguimiento de Kine): <b>tejido</b> afectado (muscular, tendón, ligamento, óseo…), <b>con o sin contacto</b>, <b>dolor al inicio (EVA 0 a 10)</b>, <b>alta médica</b>, <b>retorno a entrenar con el grupo</b> y <b>retorno a partido</b>. La app calcula sola los <b>días de baja</b> y los <b>días hasta el retorno a partido</b>. La fecha de alta de siempre ahora se llama <b>Alta kinésica</b> y sigue siendo la que cuenta para los días de baja y los informes.</li>
      <li><b>Recidiva:</b> casilla en el formulario de la lesión. Si el jugador ya tuvo otra lesión en la misma zona (o con el mismo nombre), la app te avisa y deja la casilla marcada; la puedes desmarcar.</li>
      <li><b>Examen con resultado:</b> al registrar un examen puedes anotar su resultado en una línea; se ve en la lista de registros, en el registro clínico completo y en el calendario de Kine.</li>
      <li><b>Antecedentes:</b> tarjeta en la ficha (botón Editar) con grupo sanguíneo, alergias, enfermedades, medicación habitual, lesiones y cirugías previas, apoderado y contacto de emergencia con teléfono (un toque llama) y talla y peso con el IMC.</li>
      <li><b>Documentos:</b> tarjeta en la ficha para guardar fotos de exámenes, informes médicos o consentimientos. Toca “Agregar”, toma la foto o elígela de la galería; la app la reduce sola (hasta 1400 px). Si aun así pesa demasiado, te lo dice y no la guarda. Toca la miniatura para verla en grande o eliminarla.</li>
      <li><b>Seguro:</b> la ficha muestra las activaciones del seguro del jugador con sus eventos, y un botón que lleva a Kine → Seguro.</li>
      <li><b>Franja de resumen (arriba de la ficha):</b> si el jugador tiene una lesión sin alta, aparece una insignia roja <b>“Lesionado · día N”</b> con la zona. Debajo: <b>días perdidos</b> de la temporada y de toda su carrera (cuentan los días de baja de las lesiones; las que siguen abiertas cuentan hasta hoy), lesiones y molestias de su carrera, <b>lesiones por zona</b> con un aviso como “3 lesiones en rodilla derecha” cuando hay <b>reincidencia</b>, y la tabla <b>Por temporada</b> (año, lesiones, días perdidos, atenciones y partidos con minutos).</li>
      <li><b>Historial completo:</b> reemplaza a “Registros del jugador”. Junta en orden cronológico inverso, agrupado por mes: lesiones, altas y retornos, atenciones, controles, exámenes, medicamentos, cirugías, partidos (con minutos e incidencias y el torneo si existe), seguro (solo administradores) y cambios de categoría o bajas. Toda lesión muestra su <b>gravedad</b> y, si corresponde, la insignia <b>Recidiva</b>. Activa uno o varios <b>tipos</b> con los botones redondos y filtra por <b>lesión o caso</b>, <b>zona del cuerpo</b>, <b>temporada (año)</b>, <b>período de la temporada</b> (el período lo anotan las atenciones) o busca texto sin importar tildes. Se ven 30 registros y “Ver más” muestra otros 30. El lápiz abre el registro para editarlo.</li>
      <li><b>Descargar ficha (PDF):</b> en tamaño carta con el escudo del club. Trae datos del jugador (categoría actual e historial de categorías, estado en el club, edad), resumen por temporada, lesiones con todos sus datos clínicos, cirugías y la línea de tiempo (con lo que tengas filtrado en pantalla, o todo). Las casillas <b>Incluir antecedentes y datos de contacto</b> e <b>Incluir seguro</b> vienen <b>desmarcadas</b>. El archivo se llama “Ficha - Nombre Apellido - AAAA-MM-DD.pdf”.</li>
      <li><b>Descargar historial (CSV):</b> abre en Excel (separador punto y coma). Lleva los registros que se ven con los filtros, de más antiguo a más nuevo.</li></ul>
      <p><b>Privacidad:</b> antecedentes, documentos y seguro son datos sensibles. Solo los ven y editan los administradores; <b>el cuerpo técnico no los ve</b>, y no salen en el PDF del informe. En la nube se guardan en la zona privada (la misma de los datos del seguro).</p>
      <p>Al <b>cambiar a un jugador de categoría</b>, sus antecedentes y documentos se van con él; al <b>eliminarlo definitivamente</b> se borran. Todo esto también va en los respaldos.</p>`],
    ['Torneos (Copa Libertadores y otros)', `<p>Un <b>torneo</b> es una ficha propia dentro de tu informe (Sub 15-16 o Sub 18-20): por ejemplo Copa Libertadores Sub 20, un torneo amistoso o una gira en el extranjero. Todo lo del torneo vive ahí.</p>
      <ul><li><b>Crear un torneo:</b> Partidos → pestaña <b>Torneos</b> → <b>Nuevo torneo</b>. Paso 1: nombre, tipo (Internacional, Nacional, Amistoso o Gira), país, sede, fechas, categorías y si se juega fuera de la ciudad base. Paso 2 (plegables): fases, jugadores inscritos, viaje y logística. Las fases habituales son Fase de grupos, Octavos, Cuartos, Semifinal, Tercer lugar y Final; puedes cambiarlas, quitarlas o agregar otras.</li>
      <li><b>Estado:</b> se calcula solo con las fechas: Planificado, En curso o Terminado.</li>
      <li><b>Ficha del torneo</b> (toca el torneo en la lista): pestañas <b>Resumen</b> (partidos jugados y por jugar, ganados-empates-perdidos si anotaste los resultados, atenciones y lesiones durante el torneo), <b>Partidos por fase</b>, <b>Jugadores</b>, <b>Salud</b> y <b>Viaje</b>. El marcador se lee “Wanderers – rival”.</li>
      <li><b>Carga y descanso (pestaña Jugadores):</b> se calcula sola con los minutos que anotas en cada partido. Arriba ves los partidos en orden con los días que pasaron desde el anterior. Por cada jugador: partidos jugados, minutos totales, minutos por partido (con mini barras, una por partido) y partidos seguidos. Salen dos alertas: <b>Descanso corto</b> (jugó 45 minutos o más en dos partidos con 2 días o menos de diferencia; se cuentan días de calendario, no horas) y <b>Carga alta</b> (minutos totales iguales o mayores a la mediana del grupo más un desvío estándar; solo cuando 4 o más jugadores tienen minutos). Son avisos para decidir, no reglas médicas.</li>
      <li><b>Salud antes, durante y después (pestaña Salud):</b> <b>Chequeo de salud</b> al inicio y al final: eliges para cada inscrito Apto, Limitado o Baja y una nota corta; <b>Marcar todos aptos</b> completa solo a los que aún no tienen chequeo. Debajo salen solas las <b>lesiones y molestias durante el torneo</b> (zona, gravedad, si siguió jugando o se retiró), los <b>retornos y altas</b> (quién ya volvió y quién sigue en baja), las <b>conmociones</b> del torneo, los <b>medicamentos entregados</b> dentro de las fechas del torneo y los <b>reemplazos por lesión</b>.</li>
      <li><b>Antidopaje y medicamentos:</b> en el informe de cada partido del torneo hay un bloque plegable <b>Control antidopaje</b>: marcas si hubo control, qué jugadores y una nota. En la pestaña Salud, los medicamentos siempre llevan la leyenda “Verificar en la lista de sustancias prohibidas vigente (AMA/WADA) antes de administrar”. La app no trae listas de sustancias: la verificación la haces tú en la lista oficial vigente.</li>
      <li><b>Reemplazo por lesión:</b> al registrar una atención de un partido del torneo, el bloque plegable <b>Reemplazo por lesión: informe médico</b> te deja marcar si se hizo el reemplazo y escribir el informe. Sale en el informe del torneo. En una conmoción cerebral ese texto ya viene en su propio registro y no se repite.</li>
      <li><b>Informe PDF del torneo:</b> botón <b>Informe del torneo</b> en la ficha del torneo y en Informe → Descargar PDF. Tamaño carta, con el escudo del club: portada con datos y cuerpo técnico del año; resumen (partidos jugados, G-E-P, atenciones, lesiones nuevas, conmociones, jugadores atendidos, minutos totales y atenciones en gira); partidos por fase; jugadores con minutos y alertas; lesiones y molestias; chequeos de inicio y fin; atenciones por intervención; medicamentos y antidopaje; conmociones; reemplazos con informe médico; y logística y seguro en el exterior. El archivo se llama “Informe torneo - Nombre - AAAA”. Funciona también con un torneo de un solo partido, sin partidos o sin inscritos. Los datos del seguro salen solo para administradores.</li>
      <li><b>Comparación entre torneos:</b> en la lista de torneos, cuando hay 2 o más con partidos, aparece una tabla con partidos, minutos y las atenciones y lesiones por cada 1000 minutos jugados.</li>
      <li><b>Agregar partidos:</b> el botón <b>Agregar partido al torneo</b> abre el formulario con el torneo y la fase ya elegidos. <b>Guardar y agregar otro</b> deja el formulario abierto para cargar el siguiente. Los partidos con fecha futura quedan “por jugar”. También puedes elegir el torneo y la fase al crear o editar cualquier partido (lista <b>Torneo</b>; “Sin torneo” es el campeonato normal).</li>
      <li><b>Jugadores:</b> <b>Agregar citados de la categoría</b> abre una lista con buscador y <b>Marcar todos</b>; después puedes poner el número de camiseta de cada uno.</li>
      <li><b>Viaje:</b> altitud, diferencia horaria, clima, vuelos, hotel y notas. Si marcas que el torneo se juega fuera de la ciudad base, las atenciones que registres desde sus partidos quedan con el origen <b>En gira</b>. Esas atenciones cuentan como atenciones del club igual que las demás; solo van etiquetadas y se pueden separar en el Registro clínico (filtro <b>Origen de las atenciones</b>).</li>
      <li><b>Seguro en el exterior:</b> al registrar una activación del seguro puedes anotar el país, la cobertura (seguro del club o de viaje) y la póliza. En la pestaña Viaje del torneo se ven las activaciones de los inscritos durante el torneo.</li>
      <li><b>Renombrar o eliminar:</b> si cambias el nombre del torneo se actualiza en todos sus partidos. Al eliminarlo, los partidos <b>no se borran</b>: quedan sin torneo (hay un aviso para <b>Deshacer</b>).</li>
      <li><b>Lo que ya tenías:</b> los partidos que antes tenían un torneo escrito se ordenaron solos en fichas de torneo; los informes salen igual que antes.</li></ul>`],
    ['Novedades de la versión 1.6.3', `<ul>
      <li><b>SCAT5 más corto en los informes de partido:</b> la tabla de conmociones del informe muestra solo un resumen. El informe completo de cada jugador se abre con <b>Ver informe SCAT5 completo</b> (en la pantalla del partido y en la ficha del torneo).</li>
      <li><b>Informe SCAT5 solo:</b> botón <b>Informe SCAT5 (PDF)</b> en la pantalla del partido: una ficha completa por cada conmoción de ese partido, sin el resto del informe. Antes también se sacaba desde la ficha del jugador y desde Kine.</li></ul>`],
    ['Novedades de la versión 1.6.2', `<ul>
      <li><b>SCAT5 en tres momentos:</b> el asistente largo se dividió así: <b>En cancha</b> (2–3 min, pocos toques), <b>En camarín</b> (10–15 min) y <b>Seguimiento</b> (día siguiente y siguientes, con tabla de evolución y flechas de mejora o empeora). Cada parte se guarda y se retoma cuando quieras, y la pantalla de entrada muestra tres tarjetas con su estado. Una evaluación de la versión 1.6.1 pasa sola al formato nuevo. Ver “Conmoción cerebral (SCAT5)”.</li>
      <li><b>SCAT5 pendiente en Hoy:</b> una tarjeta avisa si falta la evaluación en camarín o si pasó más de un día sin seguimiento.</li>
      <li><b>Ayuda y SCAT5 oficial:</b> la pantalla “¿Cómo uso el SCAT5 en la app?” explica los tres momentos, y puedes descargar el formulario oficial en español sin modificar (entrada del SCAT5, ayuda, formulario, Ajustes → Documentos y Manual).</li>
      <li><b>Informes:</b> el informe del partido y la Ficha SCAT5 (PDF) muestran cada evaluación con su fecha y hora y la tabla de seguimiento; en la línea de tiempo de la ficha cada evaluación es una entrada.</li></ul>`],
    ['Novedades de la versión 1.6.1', `<ul>
      <li><b>Evaluación SCAT5 dentro de la app:</b> asistente paso a paso con puntajes calculados solos, borrador que se guarda y Ficha SCAT5 en PDF. La memoria inmediata se corrigió: va de 0 a 30 (3 intentos de 10 palabras). Ver “Conmoción cerebral (SCAT5)”.</li>
      <li><b>Categoría a la que pertenece y “También juega en”:</b> ahora están separadas y explicadas con ejemplos en los datos del jugador, en “Cambiar de categoría” y en la ficha, que muestra “Pertenece a: Sub 16 · También juega en: Sub 20”.</li>
      <li><b>Casillas más claras:</b> las casillas sin marcar son un cuadro blanco con borde gris verdoso; las marcadas, verde del club con un visto blanco. Son más grandes y fáciles de tocar en el celular.</li>
      <li><b>Se quitaron</b> la “Evolución (SOAP)” de la atención y los “Tests de retorno” y “Criterios de retorno al juego” de la lesión. Las <b>Altas y retornos</b> (alta médica, retorno a entrenar con el grupo y retorno a partido), los días de baja y las marcas R/A de los calendarios siguen igual. Lo que se hubiera escrito en esos campos en versiones anteriores no se muestra más.</li></ul>`],
    ['Novedades de la versión 1.6', `<ul>
      <li><b>“Jugador de plantel”:</b> así se llama la etiqueta en la app, los informes, los PDF y los nombres de archivo. Los datos ya guardados no se tocan.</li>
      <li><b>Informe de jugadores de plantel por partidos elegidos:</b> en Partidos → “Elegir partidos” marcas uno, varios o todos y sale <b>Informe kinésico · Jugadores de plantel</b> con un resumen y una tabla por partido (nombre, categoría, minutos, atenciones Sí / No, intervención y comentarios, se retiró Sí / No). Ver “Partidos”.</li>
      <li><b>Títulos:</b> todos los informes de partido (de un partido, por categoría, general y de jugadores de plantel) dicen “Informe kinésico” arriba.</li>
      <li><b>Informe semanal por categorías:</b> en Kine → Informe semanal eliges todas las categorías, de a dos (Sub 15-16 o Sub 18-20) o una sola; el PDF y la vista incluyen solo esas.</li>
      <li><b>Calendarios con reintegro y alta:</b> el calendario de fechas importantes (Kine) y el de asistencia anual marcan el inicio del reintegro deportivo (R) y el alta (A) de cada lesión, con su leyenda. La fecha de inicio del reintegro se anota en la ficha del lesionado.</li>
      <li><b>Mayúsculas:</b> los textos de los registros (diagnósticos, exámenes, medicamentos, procedimientos, hitos, rivales, torneos, sedes…) empiezan con mayúscula, y los nombres de personas llevan mayúscula en cada palabra (de, del, la, las, los, y, van y von quedan en minúscula). También se arreglan los datos antiguos; la búsqueda sigue sin importar tildes ni mayúsculas.</li>
      <li><b>Incluir los datos de partidos en el informe general:</b> casilla en Informe, por año (apagada en 2026, encendida desde 2027). Ver “El informe y el PDF”.</li>
      <li><b>Disponibilidad para entrenar y jugar:</b> el cuadro de la ficha se llama así y trae su explicación en una línea.</li>
      <li><b>Asistencia a kinesiología:</b> el nombre completo reemplaza a “asistencia a kine” en el informe semanal y en las fichas.</li>
      <li><b>Torneos con ficha propia:</b> en Partidos hay una pestaña <b>Torneos</b> para crear, por ejemplo, la Copa Libertadores Sub 20 o una gira amistosa, con sus fases, partidos, jugadores inscritos, viaje y seguro. Los partidos y atenciones quedan dentro del torneo. El origen de atención <b>En gira / torneo fuera de sede</b> y los datos del seguro en el exterior (país, cobertura y póliza) también son nuevos.</li>
      <li><b>Torneos, parte 2:</b> en la ficha del torneo, <b>carga y descanso</b> por jugador con alertas de descanso corto y carga alta, pestaña <b>Salud</b> (chequeo de inicio y fin, lesiones durante el torneo, retornos, medicamentos con la leyenda AMA/WADA), <b>control antidopaje</b> por partido, <b>reemplazo por lesión: informe médico</b>, <b>informe PDF del torneo</b> y <b>comparación entre torneos</b>. Ver “Torneos (Copa Libertadores y otros)”.</li>
      <li><b>Conmoción cerebral (SCAT5):</b> nuevo registro de sospecha de conmoción en los partidos (botón rojo suave en la atención, en la evaluación rápida y en el informe del partido), con signos, banderas rojas, evaluación, retiro, reemplazo, derivación y aviso a la organización. Crea sola la lesión “Conmoción cerebral (sospecha)” con su retorno gradual de seis etapas y suma una sección en los informes de partido. Es un registro del kinesiólogo, no un diagnóstico. Ver “Conmoción cerebral (SCAT5)”.</li>
      <li><b>Uso diario, parte 2:</b> citados por partido y <b>Evaluación en cancha rápida</b>, Kine con lista compacta, <b>Todos asistieron</b> y alerta de controles vencidos, botones de al menos 44 px, teclado y lectores de pantalla (Enter/Espacio en las filas, ventanas con foco y Escape), búsquedas sin tildes en todas partes y un informe que se arma por tramos (“Armando informe…”) cuando hay muchos jugadores. Ver “Uso diario más rápido” y “Partidos”.</li>
      <li><b>Uso diario más rápido:</b> nueva pestaña <b>Hoy</b> (abre al entrar a una categoría y recuerda la última), selector de jugador con buscador y recientes, registro de varios jugadores con atajos, “Guardar y registrar otro”, intervenciones más usadas, plantillas, repetir última atención, lesión asociada automática y <b>Deshacer</b> al eliminar. Ver “Uso diario más rápido”.</li>
      <li><b>Historial en la ficha:</b> franja de resumen (lesionado, días perdidos, reincidencia por zona y tabla por temporada), línea de tiempo con filtros, descarga de la ficha en PDF y del historial en CSV, insignia “Lesionado” y última atención en la lista de jugadores, y buscador global con la lupa de arriba. Ver “Ficha clínica del jugador”.</li>
      <li><b>Informe de cada año:</b> al abrir la app el informe muestra el <b>año actual</b>. Si eliges otro año aparece el aviso “Estás viendo el 2025” con un enlace para volver al año actual. Los informes de años anteriores se ven <b>tal cual quedaron</b>.</li>
      <li><b>Textos por año:</b> las conclusiones, los objetivos, la firma, el cuerpo técnico y los comentarios de cada jugador se guardan en el año que estás viendo. Al escribir en un año nuevo, lo del año anterior queda guardado y no se pierde.</li>
      <li><b>Edad según el año:</b> en la ficha del informe la edad es la que tenía el jugador en el año del informe, no la de hoy.</li>
      <li><b>Cambios de categoría y bajas:</b> si un jugador cambia de categoría o sale del club, los informes de los años anteriores lo siguen mostrando con la categoría y los registros que tenía entonces. Quien ya no está inscrito no aparece en las listas del día a día (Jugadores, Registrar, Kine, partidos nuevos).</li>
      <li><b>Jugador nuevo:</b> el formulario ofrece las cuatro categorías (Sub 15, 16, 18 y 20) y lo crea en el informe de su pareja. No se puede repetir un jugador con el mismo nombre y año de nacimiento, ni siquiera si está dado de baja.</li>
      <li><b>Partidos sin fecha:</b> solo se cuentan en su año (el que estaba vigente cuando se cargaron; al iniciar una temporada nueva se quedan en el año que termina). Ponles fecha para que cuenten en el año que corresponde.</li>
      <li><b>Nombres en tres partes:</b> el jugador nuevo se crea con nombres, primer apellido y segundo apellido. Los jugadores antiguos siguen con su nombre tal cual; la app te sugiere completar los apellidos cuando abras sus datos, sin obligarte.</li>
      <li><b>Pegar lista con vista previa:</b> cada línea se marca como Nuevo, Duplicado o Faltan apellidos antes de guardar. No se descarta nada en silencio.</li>
      <li><b>Jugadores: Inscritos y Archivo.</b> El botón Eliminar de la ficha se reemplazó por <b>Dar de baja</b> (liberado, cedido, promovido o retirado): el jugador pasa al Archivo con todo su historial. También hay <b>Cambiar de categoría</b>, <b>Volver a inscribir</b> y, solo en el Archivo, <b>Eliminar definitivamente</b>.</li>
      <li><b>Iniciar temporada:</b> guía de 3 pasos (Ajustes → Nueva temporada, o el aviso del Inicio) para subir de categoría a los jugadores, dar de baja a quienes salen y dejar el año nuevo listo. Ver “Cambio de año, categorías y archivo”.</li>
      <li><b>Volver a inscribir</b> a quien estuvo en el Archivo: el tiempo que estuvo fuera no cuenta como inscrito, así que no sale en los informes de los años en que no estaba, y los años en que sí estuvo se ven igual que antes.</li>
      <li><b>Cambiar la categoría desde los datos del jugador</b> también queda con fecha (la de hoy): los informes de años anteriores siguen mostrándolo en la categoría que tenía. Para otra fecha usa “Cambiar de categoría” en su ficha.</li>
      <li><b>Informe semanal de Kine</b> de una semana pasada muestra la categoría que tenía cada jugador esa semana; los informes de partidos y de jugadores de plantel de un año muestran la categoría con que terminó ese año.</li>
      <li><b>Restaurar el respaldo de un solo informe</b>: si un jugador cambió de informe después de hacer el respaldo, no se repite (ya está en el otro con sus registros más nuevos).</li>
      <li><b>Eliminar definitivamente</b> un jugador borra también sus asistencias a kinesiología y sus datos del seguro (antes quedaban sueltos).</li>
      <li><b>Ficha clínica:</b> nuevos datos en la lesión (recidiva, tejido, contacto, dolor EVA, alta médica, retorno a entrenar y a partido), resultado de los exámenes, antecedentes del jugador, documentos adjuntos y bloque del seguro. Ver “Ficha clínica del jugador”. La fecha de alta de la lesión se llama ahora <b>Alta kinésica</b>.</li></ul>`],
    ['Novedades de la versión 1.5', `<ul>
      <li><b>Informe general Sub 15 a 20:</b> ahora hay dos opciones: <b>con fichas</b> (resumen de todas las categorías + la ficha de cada jugador) y <b>resumen sin fichas</b> (solo los datos de todas las categorías, mucho más corto). Las dos se eligen arriba en el informe y en “Descargar PDF”.</li>
      <li><b>Calendarios en lunes:</b> al tocar cualquier campo de fecha se abre un calendario propio que empieza en lunes (L M M J V S D). Tiene botones Hoy y Borrar.</li>
      <li><b>Escudo en los informes:</b> todos los PDF (informe de partidos, jugadores de plantel, registro clínico e informe semanal de kine) llevan el escudo de Wanderers con las 5 estrellas. El logo redondo de la app solo se ve al iniciar y arriba a la izquierda, junto al título.</li>
      <li><b>Jugadores de plantel:</b> la etiqueta se llama solamente <b>Jugador de plantel</b>. Se quitó el informe individual por jugador. En Partidos quedan el <b>informe general de todos los jugadores de plantel</b> y el <b>informe de un partido</b> con todos los jugadores de plantel que jugaron en él, con el escudo de Wanderers, “vs” y el escudo del rival.</li>
      <li><b>Próximo hito:</b> en la ficha del lesionado (pestaña Kine) hay un campo “Otro hito” (evaluación, test, reintegro…). En el informe semanal aparece una columna <b>Próximo hito</b>, antes de los comentarios de la semana, con lo más cercano entre control, examen, procedimiento u otro hito.</li>
      <li><b>Torneos:</b> cada torneo tiene ahora su propia ficha (ver “Torneos (Copa Libertadores y otros)”). En el informe siguen saliendo en una sección propia, aparte de “Partidos jugados”.</li>
      <li><b>Ficha del jugador con todo junto:</b> si un Sub 16 juega por la Sub 18, en su ficha de la Sub 16 salen todas sus molestias y lesiones, y las de otra categoría llevan entre paréntesis la categoría, por ejemplo “(Sub 18)”. Los totales y resúmenes del informe de cada categoría siguen separados.</li>
      <li><b>Informe de partido:</b> el encabezado muestra el escudo de Wanderers, “vs” y el escudo del rival, y el título dice “vs” antes del nombre del rival.</li>
      <li><b>Tipografía:</b> en Ajustes → Tipografía eliges la letra de la app y del PDF (Clásica, Editorial, Elegante, Moderna o Sobria). Se guarda para los dos kinesiólogos.</li>
      <li><b>Jugadores de otras categorías:</b> si un jugador de otra categoría jugó en la tuya y no tuvo nada, en el informe solo consta que jugó (tabla con sus minutos). Solo si tuvo atenciones, molestias o lesiones se agrega su ficha.</li>
      <li><b>Respaldo más seguro y chequeo de salud:</b> al importar un respaldo ves primero qué trae y, si reemplazas, se descarga antes una copia de lo actual. En Ajustes hay un <b>Chequeo de salud</b> que revisa nube, respaldo, datos y dispositivo.</li></ul>`],
    ['Íconos y estilo', `<ul><li><b>Estilo de íconos</b> (Ajustes): <b>Línea</b> (sobrio), <b>Color</b> (tus íconos originales y versiones de color) o <b>Insignia</b> (en círculo). Se aplica en toda la app y en el informe.</li>
      <li>Al elegir un ícono (por ejemplo en “Nuevo tratamiento”) puedes <b>subir tus propios íconos</b> (PNG, JPG o SVG) para cada estilo, y quitarlos con la “×”.</li></ul>`],
    ['Trabajo en línea y cuerpo técnico', `<p>Si la app está conectada a la nube (ver <i>CONFIGURAR-NUBE.md</i>):</p>
      <ul><li><b>Administradores:</b> ambos kinesiólogos entran con la misma cuenta, incluso al mismo tiempo en dispositivos distintos. Los datos, fotos e íconos se comparten. Arriba verás “Sincronizado”, “Guardando…” o “Sin conexión”.</li>
      <li><b>Sin internet</b> puedes seguir registrando; se sube automáticamente al volver la conexión.</li>
      <li><b>Cuerpo técnico:</b> en <b>Ajustes → Acceso del cuerpo técnico</b> está el link de invitación. Copiarlo o compartirlo por WhatsApp. Quienes lo abren ven <b>solo el informe</b>, sin poder editar nada. Al entrar deben <b>elegir qué informe ver</b>: solo Sub 15, solo Sub 16 o combinado (igual para Sub 18 y 20). Un letrero “Estás viendo…” les recuerda cuál es, y pueden cambiarlo arriba.</li>
      <li>El link <b>vence a los 30 días</b>. “Generar link nuevo” invalida el anterior de inmediato (úsalo también si se filtra o cambia el personal).</li>
      <li><b>Cerrar sesión</b> (Ajustes → Cuenta) borra los datos guardados en ese dispositivo; siguen en la nube.</li></ul>
      <p>Si la nube no está configurada, la app funciona solo en este dispositivo.</p>`],
    ['Respaldos y datos de ejemplo', `<ul><li><b>Respaldo completo:</b> descarga un archivo con todo. <b>Solo este informe:</b> descarga uno. <b>Importar:</b> carga un respaldo. Antes de hacer nada te muestra qué trae (informes, jugadores, casos, atenciones, partidos, seguros) y lo compara con lo que ya tienes; puedes <b>agregar</b> a lo existente o <b>reemplazar</b>. Al reemplazar, la app descarga primero una copia de lo actual (“copia-antes-de-reemplazar”) por si te arrepientes. Si el archivo está dañado o no es un respaldo de esta app, te lo avisa y no cambia nada.</li>
      <li><b>Chequeo de salud</b> (Ajustes): un vistazo a si tus datos están a salvo. Muestra si la nube está sincronizada y cuándo fue la última subida, si las reglas de Firebase permiten guardar los datos del seguro, la fecha del último respaldo, cuánto contiene la app, si hay registros sueltos (de jugadores que ya no existen, fechas ilegibles, fotos demasiado pesadas), el espacio del dispositivo y si funciona sin internet. Solo revisa: no cambia ni borra nada.</li>
      <li><b>Avisos de respaldo:</b> el <b>último día de cada mes</b> la app muestra un aviso grande para descargar el respaldo. Desde 2027, cuando se cumple un <b>trimestre, semestre o año</b>, el aviso pide además descargar el <b>informe del período</b> (el botón “Ir al informe” deja elegido el período). Si ese día no abres la app, el aviso aparece al abrirla durante los 7 días siguientes, hasta que descargues el respaldo. En Ajustes ves la fecha del último respaldo de este dispositivo.</li>
      <li>Haz un respaldo de vez en cuando; en modo solo-dispositivo es la única copia de seguridad (si borras los datos del navegador se pierde todo).</li>
      <li><b>Datos de ejemplo:</b> “Cargar datos de ejemplo” rellena jugadores y registros ficticios para ver cómo queda el informe; “Quitar datos de ejemplo” los elimina con un toque.</li></ul>`],
    ['Instalar y actualizar la app', `<ul><li><b>Instalar:</b> abre la dirección en <b>Chrome</b> → menú ⋮ → <b>Instalar aplicación</b> (o “Agregar a pantalla de inicio”). Queda como una app más y abre sin conexión.</li>
      <li><b>Actualizar:</b> cuando hay una versión nueva, la app lo avisa con un <b>banner</b> arriba (“Hay una nueva versión disponible”). Toca <b>Actualizar</b> y se recarga con las novedades; si prefieres esperar, cierra el aviso con la “×” y vuelve a aparecer más adelante. Los datos no se pierden.</li></ul>`],
    ['Botón o gesto “atrás”', `<p>Al deslizar desde el borde de la pantalla (o usar el botón atrás del celular) la app <b>no se cierra</b>: vuelve a la sección anterior o a la pestaña <b>Hoy</b>. Si ya estás en Hoy, el siguiente gesto sale de la app (te avisa antes). Con una ventana abierta, el gesto la cierra.</p>`],
    ['Problemas frecuentes', `<ul><li><b>Un partido aparece en todos los períodos:</b> no tiene fecha. Asígnala en Partidos.</li>
      <li><b>No sale el PDF o salen colores apagados:</b> en la ventana de impresión elige “Guardar como PDF”, tamaño Carta, márgenes “Ninguno” o “Predeterminado”, y activa “Gráficos de fondo”.</li>
      <li><b>Agregué un partido y no sale en el calendario del informe:</b> su fecha está fuera del período elegido (por ejemplo otro año). En Partidos aparece un aviso con el partido afectado; corrige la fecha o cambia el período.</li>
      <li><b>Un jugador no aparece en una lista:</b> revisa que tenga la categoría correcta, o cambia de categoría con el selector de arriba. Si lo diste de baja, está en <b>Jugadores → Archivo</b>.</li>
      <li><b>“Sin conexión” permanente:</b> revisa tu internet; los cambios se guardan y suben al volver.</li>
      <li><b>El link del cuerpo técnico dejó de funcionar:</b> venció o fue reemplazado. Genera uno nuevo en Ajustes.</li></ul>`]
  ];
  K.manualHTML = () => `<div class="card manual">
    <p class="sub" style="margin-top:0">Todo lo que se puede hacer con la aplicación. Toca una sección para abrirla.</p>
    ${S.map(([t, c]) => `<details><summary>${t}</summary><div class="manual-c">${c.replace('{{SCAT5_OFICIAL}}', K.scat5 && K.scat5.enlaceOficialHTML ? ' ' + K.scat5.enlaceOficialHTML('chico') : '')}</div></details>`).join('')}${K.versionHTML()}</div>`;
  K.versionHTML = () => `<div class="version-app"><b>Versión de la app: ${K.version}</b><span>${K.rol === 'admin' ? 'Modo en línea · administrador' : K.rol === 'tecnico' ? 'Modo en línea · cuerpo técnico' : 'Datos solo en este dispositivo'}</span></div>`;
})();
